-- PG 集成测试用的完整 schema（**由生成器产出，勿手改**）。
--
-- 为什么放在测试里：PG 集成测试需要一个与生产同构的库（identity 主键、citext、外键级联、触发器、索引），
-- 而在测试容器里跑生成器需要 node:sqlite，环境不一定有。因此把生成结果固化成 fixture：
--   node ops/scripts/pg/gen-schema.mjs <sqlite.db> <out.sql>   → 追加 post-schema.pg.sql
-- 迁移新增表/列时**必须重新生成**（否则测试跑的是旧结构，会漏掉新方言）。
--
-- 用法：	est/helpers/pgTestDb.ts 会在 microclass_test 库里 DROP SCHEMA public CASCADE 后整份执行。
-- 生成器输出的 COLLATE NOCASE 已由 post-schema 的 citext 承接（见 docs/postgres-migration.md §9 #6）。
BEGIN;

CREATE TABLE "announcements" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" text NOT NULL,
  "body" text NOT NULL DEFAULT '',
  "level" text NOT NULL DEFAULT 'info',
  "pinned" bigint NOT NULL DEFAULT 0,
  "published" bigint NOT NULL DEFAULT 1,
  "created_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD HH24:MI:SS'),
  "created_by" bigint
);

CREATE TABLE "attempts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "client_id" text NOT NULL,
  "lesson_id" bigint NOT NULL,
  "answers" text DEFAULT '[]',
  "score" bigint DEFAULT 0,
  "total" bigint DEFAULT 0,
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint,
  "user_id" bigint
);

CREATE TABLE "audit_logs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" bigint,
  "actor_name" text,
  "action" text NOT NULL,
  "target_type" text,
  "target_id" text,
  "detail" text,
  "ip" text,
  "request_id" text,
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint
);

CREATE TABLE "bank_folders" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parent_id" bigint,
  "name" text NOT NULL,
  "sort" bigint NOT NULL DEFAULT 0,
  "created_at" text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE "bank_health_cache" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "computed_at" text NOT NULL,
  "payload" text NOT NULL,
  CONSTRAINT "bank_health_cache_check_1" CHECK (id = 1)
);

CREATE TABLE "banks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "lesson_id" bigint,
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint,
  "kind" text DEFAULT 'lesson',
  "subject" text DEFAULT '',
  "book" text DEFAULT '',
  "course_id" bigint,
  "question_count" bigint NOT NULL DEFAULT 0,
  "section" text NOT NULL DEFAULT '',
  "folder_id" bigint
);

CREATE TABLE "categories" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "sort" bigint DEFAULT 0
);

CREATE TABLE "courses" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "description" text DEFAULT '',
  "sort" bigint DEFAULT 0,
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint,
  "category_id" bigint,
  "cover" text DEFAULT '',
  "published" bigint DEFAULT 1,
  "folder_root_id" text,
  "folder_path" text,
  "last_scan_at" bigint
);

CREATE TABLE "exam_attempts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "exam_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "answers" text DEFAULT '[]',
  "score" bigint DEFAULT 0,
  "total" bigint DEFAULT 0,
  "passed" bigint DEFAULT 0,
  "used_seconds" bigint DEFAULT 0,
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint
);

CREATE TABLE "exam_questions" (
  "exam_id" bigint NOT NULL,
  "question_id" bigint NOT NULL,
  "sort" bigint DEFAULT 0,
  "score" double precision DEFAULT 0,
  "section" text DEFAULT '',
  PRIMARY KEY ("exam_id", "question_id")
);

CREATE TABLE "exams" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" bigint NOT NULL,
  "title" text NOT NULL,
  "description" text DEFAULT '',
  "duration_minutes" bigint DEFAULT 60,
  "pass_score" bigint DEFAULT 60,
  "status" text DEFAULT 'draft',
  "created_at" bigint DEFAULT (EXTRACT(EPOCH FROM now()))::bigint,
  "structure" text DEFAULT '[]',
  "difficulty_target" text DEFAULT '',
  "total_score" bigint DEFAULT 100,
  "start_at" bigint DEFAULT 0,
  "end_at" bigint DEFAULT 0,
  "attempt_limit" bigint DEFAULT 0,
  "shuffle_questions" bigint DEFAULT 0,
